% Generic awareness about the system.:
if ~exist('src200sym','var')
    src200sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei200_align_sym3.sqw');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src200sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);lz 0 1;keep_figure; %[output:04dacedb]
w2_000b = cut(src200sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 1; keep_figure; %[output:3bb16a47]


data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits\' %[output:0c3edc9f]
fit_cuts_file = 'multicuts_fit_dataGP_ei200meV.mat' %[output:5c3cac6c]
cuts_res_file = fullfile(data_path,fit_cuts_file);
% retrieve selected cuts and masks used to improve the cuts
if ~exist('cuts2fit200GP','var')
    cuts2fit200GP = recover_cuts_2fit(cuts_res_file,'cuts2fit200GP');
end

hc.log_level = ll;

othrEi200cut111 = {[-0.1,0.1],[-0.1,0.1],[0,2,150]};
file = src200sym.full_filename %[output:537013d6]
[~,fname] = fileparts(file);

%%
% generic awarenes about the system. Rotation plane
hc.log_level = -2;

w2_001 = cut(src200sym,line_proj('offset',[0,0,1]),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_001);lz 0 1; keep_figure; %[output:96a88f75]

w2_00 = cut(src200sym,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
[fbase,axbase]=plot(w2_00);lz 0 1;  %[output:7d2d3fe4]
keep_figure; %[output:7d2d3fe4]

hc.log_level = ll;

%%
% GP offset 110; min FF variation
hc.log_level = -2;
liny %[output:663e8e3c]

lp111m = line_proj([-1,1,1],[-1,-1,0],'offset',[1,1,0]);
w2_200off110m = cut(src200sym,lp111m,[0,0.01,1],othrEi200cut111{:});
w2_200off110m.full_filename = [fname,', w2_200off110m'];
fh= plot(w2_200off110m); lz 0 4; %[output:0a1c6f4d]
[w2_200off110mf,cuts2fit200GP] = draw_masks_helper(fh,cuts2fit200GP,'msk110_dir_m111',1);
plot(w2_200off110mf); lz 0 1;keep_figure %[output:0a1c6f4d]
%
lp111p = line_proj([1,-1,1],[1,1,0],'offset',[1,1,0]);
w2_200off110p = cut(src200sym,lp111p,[0,0.01,1],othrEi200cut111{:});
w2_200off110p.full_filename = [fname,', w2_200off110p'];
fh = plot(w2_200off110p); lz 0 4; %[output:435539d5]
[w2_200off110pf,cuts2fit200GP] = draw_masks_helper(fh,cuts2fit200GP,'msk110_dir_p111',1);
plot(w2_200off110mf); lz 0 1;keep_figure; %[output:435539d5]

% cut for building spaghetti pannel
w2e200GPoff110 = sqw_op_bin_pixels({w2_200off110m,w2_200off110p}, ...
    @move_all_to_proj, ...
    {[lp111m,lp111p]}, ...
    lp111m,[0,0.01,1],othrEi200cut111{:},'-combine');
plot(w2e200GPoff110);liny; lz 0 1;keep_figure; %[output:2cb5e6ef]

% cut to do fit
w2e200GPoff110f = sqw_op_bin_pixels({w2_200off110mf,w2_200off110pf}, ...
    @move_all_to_proj, ...
    {[lp111m,lp111p]}, ...
    lp111m,[0,0.01,0.35],othrEi200cut111{:},'-combine');
plot(w2e200GPoff110f);liny; lz 0 1;keep_figure; %[output:37ef1024]


cuts2fit200GP.cuts_off110 = w2e200GPoff110;
cuts2fit200GP.cuts_off110f = w2e200GPoff110f;
hc.log_level = ll;
%%
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
allJfitfile = fullfile(scuts_path,'e200e400GPffCuts.mat');
if ~exist('GPFFfitDte200e400','var')
    GPFFfitDte200e400 = [];
end
GPFFfitDte200e400 = save_selected_cuts(GPFFfitDte200e400,allJfitfile,'Ei200_off110GPmff',cut(w2e200GPoff110f,[0,0.01,0.3],[6,2,120])); %[output:79ac5791]

%%
% GP offset 200; min FF direction
hc.log_level = -2;
liny %[output:1fff6b2f]

lp111m2 = line_proj([-1,1,1],[-1,-1,0],'offset',[2,0,0]);
w2_200off200m = cut(src200sym,lp111m2,[0,0.01,1],othrEi200cut111{:});
w2_200off200m.full_filename = [fname,', w2_200off200m'];
fh= plot(w2_200off200m); lz 0 4; %[output:9ef2dd5f]
[w2_200off200mf,cuts2fit200GP] = draw_masks_helper(fh,cuts2fit200GP,'msk200_dir_m111',1);
plot(w2_200off110mf); lz 0 1;keep_figure %[output:9ef2dd5f]
%
lp111p2 = line_proj([1,-1,1],[1,1,0],'offset',[0,2,0]);
w2_200off200p = cut(src200sym,lp111p2,[0,0.01,1.5],othrEi200cut111{:});
w2_200off200p.full_filename = [fname,', w2_200off200p'];
fh = plot(w2_200off200p); lz 0 4; %[output:1453a145]
[w2_200off200pf,cuts2fit200GP] = draw_masks_helper(fh,cuts2fit200GP,'msk200_dir_p111',1);
plot(w2_200off200pf); lz 0 1;keep_figure; %[output:1453a145]

w2e200GPoff200 = sqw_op_bin_pixels({w2_200off200m,w2_200off200p}, ...
    @move_all_to_proj, ...
    {[lp111m2,lp111p2]}, ...
    lp111m2,[0,0.01,1],othrEi200cut111{:},'-combine');
plot(w2e200GPoff200);liny; lz 0 1;keep_figure; %[output:0798087d]

w2e200GPoff200f = sqw_op_bin_pixels({w2_200off200mf,w2_200off200pf}, ...
    @move_all_to_proj, ...
    {[lp111m2,lp111p2]}, ...
    lp111m2,[0,0.01,0.5],othrEi200cut111{:},'-combine');
plot(w2e200GPoff200f);liny; lz 0 1;keep_figure; %[output:5a36eef7]


cuts2fit200GP.cuts_off200 = w2e200GPoff200;
cuts2fit200GP.cuts_off200f = w2e200GPoff200f;
hc.log_level = ll;
%%
save(cuts_res_file,'cuts2fit200GP','-v7.3');
%%
GPFFfitDte200e400 = save_selected_cuts(GPFFfitDte200e400,allJfitfile,'Ei200_off200GPmff',cut(w2e200GPoff200f,[0,0.01,0.3],[6,2,130])); %[output:536cbb11]
%%
hc.log_level = -2;

bg_200o11 = cut(src200sym,line_proj([-1,1,1],[-1,-1,0],'offset',[3,3,0]),[-1,1],othrEi200cut111{:}) %[output:7e98a8d1]
%plot(bg_400o11);lz 0 0.5; keep_figure;
acolor k;
plot(bg_400o11); logy;
bg_200o02 = cut(src200sym,line_proj([1,1,1],[-1,1,0],'offset',[2,4,0]),[-1,1],othrEi200cut111{:});
%
%plot(bg_400o02);lz 0 0.5; keep_figure;
acolor g;
pd(bg_400o02);

hc.log_level = ll;
%%
hc.log_level = -2;
w111_cuts = repmat(sqw,1,2);

w111_cuts(1) = w2_400o11 - replicate(bg_400o11,w2_400o11); plot(w111_cuts(1)); liny; lz 0 0.5;keep_figure; w111_cuts(1)  = cut(w111_cuts(1) ,[0,0.02,1],[]); %[output:7110d031]
w111_cuts(2) = w2_400o02 - replicate(bg_400o02,w2_400o02); plot(w111_cuts(2)); lz 0 0.5;keep_figure;w111_cuts(2)  = cut(w111_cuts(2) ,[0,0.02,1],[]); %[output:585bb1da]


hc.log_level = ll;

%%
if ~exist('magi','var')
    magi = MagneticIons();
end
hc.log_level = -2;

disp('*************************************************') %[output:9cb1aa35]
disp('****  MAG_FF CORRECTED DATA  ********************') %[output:8da00bf8]
disp('*************************************************') %[output:294029e6]

w111_cc = repmat(sqw,1,numel(w111_cuts)) %[output:3487d645]
for i=1:numel(w111_cuts) %[output:group:53cf44b7]
    w111_cc(i) = magi.correct_mag_ff(w111_cuts(i));
    plot(w111_cc(i)); lz 0 2;keep_figure;drawnow     %[output:471e533c] %[output:21eb336f]
end %[output:group:53cf44b7]

hc.log_level = ll;

%[output:18c1cc8d] %[output:28e8830e] %[output:5289be69] %[output:7c482ea5] %[output:6deb8186] %[output:0bf5c823] %[output:1e787ee7] %[output:3fbbe3cb] %[output:925050aa] %[output:4fd5590b] %[output:9b400b25] %[output:7eb9e1ef]
%%
sources = num2cell(w111_cc);
src_proj = arrayfun(@(x)x.data.proj,w111_cc);
targ_proj = w111_sym(1).data.proj;
targ_proj.offset = [0,0,0];
w2_400Sum = sqw_op_bin_pixels(sources,@move_all_to_proj,{src_proj}, ...
    targ_proj,[0,0.005,0.5],[-0.1,0.1],[-0.1,0.1],[0,4,450], ...
    '-combine');
w2_400Sum.full_filename = [fname,',  ei400_allSym; bg_removed; ff_corrected'];

plot(w2_400Sum); lz 0 1;keep_figure; %[output:48102594]
%%
ff = gcf;
savefig(ff,'sGP_Ei400_allSym_bg_rem_ff_corr');

